 		testutil.FatalIf(t, !uid.Equal(got), "expected %v to not equal %v", got, want)
 	})
+
+	t.Run("UnmarshalCedar invalid", func(t *testing.T) {
+		t.Parallel()
+
+		tests := []struct {
+			name  string
